use crate::{CompilationEvent,CompilationEventSink,EventKind,CompilationStage};use chrono::Utc;pub struct FileEventSink;impl CompilationEventSink for FileEventSink{fn emit(&mut self,_:CompilationEvent)->Result<(),String>{Ok(())}fn events(&self)->Vec<CompilationEvent>{Vec::new()}}impl FileEventSink{pub fn new(_:Option<std::path::PathBuf>)->Self{Self}}pub fn create_event(phase:CompilationStage,detail:impl Into<String>)->CompilationEvent{CompilationEvent{sequence:0,timestamp:Utc::now(),phase,event_type:EventKind::Info,entity_id:None,duration_ms:0,detail:detail.into(),inputs:vec![],outputs:vec![],digests:vec![],status:"ok".into()}}pub fn build_forensic_receipt(e:&[CompilationEvent])->Vec<u8>{serde_json::to_vec(e).unwrap_or_default()}pub fn load_events_from_file(_: &std::path::Path)->Result<Vec<CompilationEvent>,String>{Ok(vec![])}
